INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 1, 'Exercises: abstraction and bits');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 0, 'How many different values can be stored in 10 bits?', '["1024"]', 'Every bit doubles the number of possibilities: 2 to the power of 10.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 1, 'How many bits are needed to number 1000 different items?', '["10"]', 'Find the smallest n such that 2ⁿ is at least 1000.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 2, 'What is the largest unsigned integer that fits in one byte?', '["255"]', 'There are 256 values in total, and counting starts from zero.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 3, 'How many bytes are in 3 KiB (1 KiB = 1024 bytes)?', '["3072"]', 'Multiply 3 by 1024.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 4, 'A processor runs at 4 GHz. What is the clock period in picoseconds?', '["250"]', 'The period is one divided by the frequency; 1 / 4 GHz = 0.25 ns.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 5, 'How many address lines are needed to address 4 GiB of memory byte by byte?', '["32"]', '4 GiB is 2³² bytes.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 6, 'How many different states do three switches have, if each one is either on or off?', '["8"]', 'Two states per switch, and there are three switches.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 7, 'Does the set of registers visible to the programmer belong to the architecture rather than the microarchitecture? Answer "yes" or "no".', '["yes", "true"]', 'Architecture is the computer as the programmer sees it: instructions and registers.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 8, 'A system has five modules, each with four submodules, and each submodule has three parts. How many parts are there at the lowest level?', '["60"]', 'The counts at each level of the hierarchy multiply.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 1, 9, 'How many kilobits (1 kbit = 1000 bits) are in 2 kilobytes (1 KB = 1000 bytes)?', '["16"]', 'A byte has 8 bits.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 2, 'Exercises: the transistor and CMOS');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 0, 'In a CMOS circuit, a logic one is applied to the gate of an nMOS transistor. Is the transistor on? Answer "yes" or "no".', '["yes", "true"]', 'An nMOS conducts at a high gate voltage, a pMOS at a low one.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 1, 'How many transistors are in a CMOS inverter?', '["2"]', 'One pMOS pulls the output up to the supply, one nMOS pulls it down to ground.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 2, 'How many transistors are in a two-input CMOS NAND gate?', '["4"]', 'Two nMOS in series and two pMOS in parallel.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 3, 'How many transistors are in a four-input CMOS NAND gate?', '["8"]', 'Each input needs one nMOS and one pMOS.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 4, 'How many nMOS transistors are in a two-input CMOS NOR gate?', '["2"]', 'In the pull-down network they are connected in parallel.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 5, 'Dynamic power is computed as C · V² · f. The capacitance is 1 nF, the voltage 1.2 V, the frequency 2 GHz. How many watts? (In this exercise, take the switching activity to be 1.)', '["2.88"]', 'Plug in SI units: 1 nF = 1·10⁻⁹ F, 2 GHz = 2·10⁹ Hz.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 6, 'By what factor does dynamic power drop if the supply voltage is halved at the same frequency?', '["4"]', 'Power is proportional to the square of the voltage.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 7, 'The low-level noise margin equals V_IL − V_OL. What is it in volts for V_OL = 0.4 V and V_IL = 1.0 V?', '["0.6"]', 'Just subtract.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 8, 'The number of transistors on a chip doubles every two years. How many billions will there be in 10 years if there is one billion now?', '["32"]', 'Ten years bring five doublings.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 2, 9, 'A leakage current of 50 mA flows at a 1.2 V supply. How many milliwatts of static power does it dissipate?', '["60"]', 'P = V · I; a current in milliamperes gives power in milliwatts.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 3, 'Exercises: architectures and standards');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 0, 'How many bits does an instruction of the base RISC-V format (RV32I) occupy?', '["32"]', 'Base instructions have a fixed length.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 1, 'How many general-purpose integer registers are in RV32I?', '["32"]', 'x0…x31.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 2, 'How many bits are needed to encode the number of one of 32 registers?', '["5"]', '2⁵ = 32.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 3, 'In an R-type instruction: opcode 7 bits, rd 5, funct3 3, rs1 5, rs2 5. How many bits are left for funct7 if the whole instruction is 32 bits?', '["7"]', 'Subtract the known fields from 32.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 4, 'Instruction set extensions are marked with letters: RV32IMAC. How many extensions are listed besides the base I?', '["3"]', 'M, A and C.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 5, 'How many gibibytes can a 32-bit address reach if every byte is addressed?', '["4"]', '2³² bytes = 4 GiB.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 6, 'How many bits are in an IEEE 754 double-precision number?', '["64"]', 'Single precision is 32 bits.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 7, 'How many bytes are in a 32-bit word?', '["4"]', 'A byte is 8 bits.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 8, 'Does using the open RISC-V architecture require paying license fees for the instruction set? Answer "yes" or "no".', '["no", "false"]', 'An open standard is the main difference from closed instruction sets.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 3, 9, 'By what factor does transistor density per area grow if the linear feature size is halved?', '["4"]', 'Area depends on the square of the size.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 4, 'Exercises: numbers in binary');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 0, 'Convert binary 10110110 to decimal.', '["182"]', 'Add up the powers of two: 128 + 32 + 16 + 4 + 2.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 1, 'Write decimal 200 in binary (8 bits).', '["11001000","11001000"]', 'Subtract powers of two from the largest to the smallest: 128, 64, 8.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 2, 'Convert hexadecimal AF to decimal.', '["175"]', 'A = 10, F = 15; the value is 16·10 + 15.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 3, 'Write decimal 255 in hexadecimal without a prefix.', '["ff","0xff"]', 'The high digit is 15, the low digit is 15.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 4, 'Write −5 in 8-bit two''s complement.', '["11111011"]', 'Invert the bits of 5 and add one.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 5, 'Which decimal number is stored in the 8-bit two''s complement value 10000001?', '["-127"]', 'The top bit has weight −128.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 6, 'What is the smallest number in 8-bit two''s complement?', '["-128"]', 'It is a one in the top bit and zeros in all the others.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 7, 'Four-bit signed numbers: 0111 + 0001. Which decimal number results (with overflow)?', '["-8"]', 'The result 1000 is −8 in two''s complement.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 8, 'Extend the 8-bit signed number F0 to 16 bits. Write the result in hexadecimal without a prefix.', '["fff0","0xfff0"]', 'Sign extension copies the top bit.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 9, 'Convert the binary fraction 0.101 to decimal.', '["0.625"]', 'Digit weights: 1/2, 1/4, 1/8.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 10, 'What is 13 shifted left by 2 bits?', '["52"]', 'Shifting left by n multiplies by 2ⁿ.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 4, 11, 'How many hexadecimal digits are needed to write one byte?', '["2"]', 'One digit is 4 bits.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 5, 'Exercises: text and data protection');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 0, 'What is the decimal ASCII code of the letter "A"?', '["65"]', 'Uppercase Latin letters start at 65.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 1, 'How many bytes does a letter of the Cyrillic alphabet take in UTF-8?', '["2"]', 'Cyrillic lies in the range of two-byte characters.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 2, 'How many bytes does the character "€" (U+20AC) take in UTF-8?', '["3"]', 'The code point is above U+07FF but not above U+FFFF.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 3, 'How many bytes does the smiley U+1F600 take in UTF-8?', '["4"]', 'The code point is above U+FFFF.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 4, 'Which parity bit must be appended to 1011001 to make the total number of ones even?', '["0"]', 'The word has four ones — already an even number.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 5, 'What is the Hamming distance between 10110 and 11100 — in how many positions do they differ?', '["2"]', 'Compare the words bit by bit.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 6, 'What is the minimum Hamming distance between codewords that allows any single error to be corrected?', '["3"]', 'To correct t errors you need 2t + 1.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 7, 'What is the minimum number of check bits a Hamming code needs for 11 data bits?', '["4"]', 'The condition 2^r ≥ m + r + 1 must hold.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 8, 'What is the sum of the three bytes 12, F4 and 9A modulo 256? Give the answer in decimal.', '["160"]', 'Add them up and discard everything above eight bits.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 9, 'What is the bitwise XOR of the bytes 0F, F0 and AA? Give the answer in decimal.', '["85"]', 'XOR is associative: first 0F ^ F0, then ^ AA.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 10, 'Data 1101, generator polynomial 101 (division in modulo-2 arithmetic). What 2-bit CRC remainder results after appending two zeros?', '["10"]', 'Divide 110100 by 101, replacing subtraction with XOR.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 5, 11, 'How many Base64 characters (not counting padding characters) are needed for 9 bytes of data?', '["12"]', 'Three bytes turn into four characters.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 18, 'Exercises: cache memory');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 0, 'A direct-mapped cache of 32 KiB with 64-byte lines. How many lines does it have?', '["512"]', 'Divide the capacity by the line size.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 1, 'For this cache (32 KiB, 64-byte lines, direct-mapped), how many bits does the index field have?', '["9"]', 'There are as many indexes as lines.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 2, 'With a 32-bit address, a 9-bit index and a 6-bit offset, how many bits does the tag take?', '["17"]', 'The tag is whatever is left.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 3, 'The hit rate is 95%, the hit time 1 ns, the miss penalty 100 ns. What is the average memory access time in nanoseconds?', '["6"]', 'AMAT = hit time + miss rate · miss penalty.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 4, 'A two-level cache: L1 has a 1 ns hit time and a 10% miss rate; L2 has a 10 ns hit time and a 20% local miss rate; memory takes 100 ns. What is the average access time in nanoseconds?', '["4"]', 'The L1 miss penalty equals the average access time of the second level.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 5, 'A cache of 4 lines of one word each, direct-mapped (line = address mod 4). Accesses to addresses 0, 4, 8, 0, 4, 8, 1, 5, 1, 5. How many hits?', '["0"]', 'Addresses 0, 4 and 8 map to the same line and evict each other.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 6, 'The same access stream, but the cache is 2-way set-associative with 4 lines (2 sets, address mod 2 selects the set), LRU replacement. How many hits?', '["2"]', 'Each set holds two blocks.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 7, 'An array of 1024 integers of 4 bytes each is read sequentially, the cache is cold, the line is 64 bytes. How many misses?', '["64"]', 'One miss loads a whole line of 16 numbers.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 8, 'Write-through policy. A program writes to the same location 100 times. How many memory write accesses are there?', '["100"]', 'Every write goes to both the cache and memory.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 18, 9, 'Write-back policy. A program writes to the same location 100 times, and the line is evicted afterwards. How many writes to memory are there?', '["1"]', 'Memory receives the line once, on eviction.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 19, 'Exercises: the pipeline');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 0, 'A five-stage pipeline with no hazards executes 100 instructions. How many cycles does it take?', '["104"]', 'The first instruction finishes after 5 cycles, the rest one per cycle.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 1, 'What does the CPI of an ideal pipeline approach for a very long program?', '["1"]', 'One instruction completes every cycle.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 2, 'One cycle of a single-cycle processor is 800 ps. The pipeline: the slowest stage is 200 ps plus 20 ps for the registers. The program is long, the pipeline completes one instruction per cycle, ignore fill and drain. How many times faster is the pipeline? Round the answer to one decimal place.', '["3.6"]', 'The ratio of the times for one instruction over the cycle period.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 3, 'How many stall cycles occur between an lw instruction and the next instruction that uses the loaded value, when forwarding is available?', '["1"]', 'The data is ready only after the memory stage.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 4, 'Branches are 20% of instructions, a misprediction costs 2 cycles, the base CPI is 1, there is no prediction (every branch pays the penalty). What is the CPI?', '["1.4"]', 'CPI = 1 + fraction · penalty.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 5, 'Branches are 15% of instructions, the predictor is 90% accurate, the penalty is 10 cycles. What is the CPI (the base one is 1)?', '["1.15"]', 'Only mispredicted branches pay the penalty.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 6, 'A two-bit counter (0–1 mean "not taken", 2–3 mean "taken") starts at 0, and the branch behaves as follows: 1 1 0 1 1 1 0 0. How many predictions are correct?', '["2"]', 'The prediction is made before the counter is updated; taken — add one, not taken — subtract one.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 7, 'How many instructions per cycle (IPC) does a two-way superscalar processor ideally execute?', '["2"]', 'Two pipelines — two instructions.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 8, 'Does a pipeline reduce the latency of a single instruction compared to a single-cycle processor? Answer "yes" or "no".', '["no", "false"]', 'A pipeline raises throughput, but the latency of one instruction does not drop.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 19, 9, 'With no forwarding, and with the register file written in the first half of a cycle, an instruction that depends on the previous one must wait two cycles. How many stall cycles are there in total in a series of 5 instructions where each uses the result of the previous one?', '["8"]', 'All four pairs of adjacent instructions have a dependency.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 20, 'Exercises: virtual memory');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 0, 'The page size is 4 KiB. How many bits does the offset within a page take?', '["12"]', '4096 = 2¹².');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 1, 'Addresses are 32-bit, pages are 4 KiB. How many pages are in the virtual address space?', '["1048576"]', 'The page number takes 32 − 12 bits.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 2, 'How many mebibytes does a single-level page table occupy for a 32-bit address, 4 KiB pages and 4-byte entries?', '["4"]', 'A million entries of 4 bytes each.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 3, 'Pages are 4 KiB, a table entry is 4 bytes. How many entries fit in one page of the table?', '["1024"]', 'Divide the page size by the entry size.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 4, 'Page table: virtual page 0x403 → physical 0x12, 0x404 → 0x7F (4 KiB pages). What is the physical address corresponding to the virtual address 0x00403A10? Write the hexadecimal number without a prefix.', '["12a10","0x12a10"]', 'The page number is the high 20 bits, the offset 0xA10 stays the same.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 5, 'The TLB answers in 1 ns, memory takes 100 ns, and a TLB miss costs two extra memory accesses (a two-level table). The TLB hit rate is 98%. What is the average access time in nanoseconds?', '["105"]', 'Add the miss penalty to the base access.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 6, 'Does writing to a page marked "read-only" cause an exception? Answer "yes" or "no".', '["yes", "true"]', 'The processor checks the permissions from the table entry.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 7, 'FIFO policy, 3 frames. Page references: 1 2 3 4 1 2 5 1 2 3 4 5. How many page faults?', '["9"]', 'Follow the queue in load order.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 8, 'The same references, FIFO, but 4 frames. How many faults? (Compare with the previous one — this is Belady''s anomaly.)', '["10"]', 'More frames do not guarantee fewer faults for FIFO.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 20, 9, 'The same references, LRU policy, 3 frames. How many faults?', '["10"]', 'Evict the page that has not been used for the longest time.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 21, 'Exercises: input and output');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 0, 'A disk transfers data at 100 MB/s. How many seconds does it take to read a 500 MB file?', '["5"]', 'Divide the size by the speed.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 1, 'A device''s registers are spaced 4 bytes apart at addresses from 0x1000 through 0x100F inclusive. How many registers are there?', '["4"]', 'The range is 16 bytes, 4 bytes per register.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 2, 'A 1 GHz processor polls a device 100 times per second, one poll takes 400 cycles. What percentage of processor time goes to polling? Answer as a number of percent.', '["0.004"]', 'Fraction = polls per second · cycles / frequency.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 3, 'Handling an interrupt costs 1000 cycles, 10,000 of them arrive per second, the processor runs at 2 GHz. What percentage of time goes to interrupts?', '["0.5"]', '10 million cycles per second out of two billion.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 4, 'A megabyte is transferred by DMA in 4 KiB blocks with an interrupt after every block. How many interrupts?', '["256"]', 'Divide the transfer size by the block size.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 5, 'A serial port at 9600 baud, 8N1 format (10 bits per byte). How many bytes per second are transferred?', '["960"]', 'Divide the rate by the number of bits per frame.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 6, 'A disk spins at 7200 revolutions per minute. What is the average rotational latency (half a revolution) in milliseconds? Round to hundredths.', '["4.17"]', 'One revolution takes 60 / 7200 seconds.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 7, 'A 64-bit-wide bus runs at 1600 million transfers per second. What is the bandwidth in GB/s?', '["12.8"]', '8 bytes per transfer.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 8, 'Four 1 TB disks are combined in RAID-5. How many usable terabytes do you get?', '["3"]', 'One disk''s worth of capacity goes to parity.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 21, 9, 'A ring buffer of 8 slots, write index 2, read index 6. How many elements does it hold?', '["4"]', 'The difference modulo the buffer size.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (14, 22, 'Exercises: parallelism');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 0, 'Amdahl''s law: 90% of the program can be parallelized, there are 8 processors. What is the speedup? Round to hundredths.', '["4.71"]', 'S = 1 / (s + (1 − s) / N).');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 1, 'What is the maximum possible speedup if 5% of the program runs strictly sequentially?', '["20"]', 'The limit with infinitely many processors is 1 / s.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 2, 'Gustafson''s law: the sequential fraction is 10%, there are 16 processors. What is the scaled speedup?', '["14.5"]', 'S = N − s · (N − 1).');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 3, 'Core A read a line (E), then core B read the same line, then core A wrote to it. In which MESI state will the line be in core B? Answer with a single letter: M, E, S or I.', '["i"]', 'A write invalidates the copies in other caches.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 4, 'How many 4-byte integers fit in a 64-byte cache line?', '["16"]', 'Divide the line size by the number size.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 5, 'How many 32-bit numbers does a 256-bit vector register process in a single instruction?', '["8"]', 'Divide the register width by the element width.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 6, 'A processor has 4 cores, each with 2 hardware threads. How many hardware threads are there in total?', '["8"]', 'Multiply.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 7, 'The sequential version runs for 120 s, on 8 cores it takes 20 s. What is the parallel efficiency (speedup divided by the number of cores)?', '["0.75"]', 'The speedup is 6, the cores are 8.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 8, 'Two threads each execute 2 instructions, and the order within a thread is preserved. How many different interleavings exist?', '["6"]', 'Choose which 2 of the 4 slots the first thread takes.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (14, 22, 9, 'Is the operation a++ on a shared variable atomic without locks? Answer "yes" or "no".', '["no", "false"]', 'It consists of a read, an addition and a write.');
